INSERT INTO "public"."agent_model_provider" VALUES ('38db68d7a9e8aed99705928a09d917d7', 'system', 'openai', 'OpenAI', NULL, NULL, '["TEXT_EMBEDDING","LLM"]', '[{"name":"apiKey","label":"API Key","type":"SECRET","required":true,"placeholder":null,"defaultValue":null,"secret":true},{"name":"baseUrl","label":"Base URL","type":"TEXT","required":false,"placeholder":"https://api.openai.com","defaultValue":"https://api.openai.com","secret":false}]', '{"TEXT_EMBEDDING":[{"name":"dimensions","label":"输出向量维度","type":"INT","min":8.0,"max":8192.0,"step":1.0,"precision":null,"defaultValue":1536,"placeholder":null,"help":"留空使用模型默认维度；某些模型可通过 dimensions 参数降维","required":false}],"LLM":[{"name":"temperature","label":"Temperature","type":"FLOAT","min":0.0,"max":2.0,"step":0.1,"precision":2,"defaultValue":0.7,"placeholder":null,"help":"较高值输出更随机，较低值更聚焦","required":false},{"name":"topP","label":"Top P","type":"FLOAT","min":0.0,"max":1.0,"step":0.1,"precision":2,"defaultValue":1.0,"placeholder":null,"help":"核采样：只从累积概率 top P 的词里采样","required":false},{"name":"maxTokens","label":"最大生成 Tokens","type":"INT","min":1.0,"max":32000.0,"step":1.0,"precision":null,"defaultValue":2048,"placeholder":null,"help":"单次输出上限；模型上下文一般是 context - maxTokens","required":false},{"name":"presencePenalty","label":"Presence Penalty","type":"FLOAT","min":-2.0,"max":2.0,"step":0.1,"precision":2,"defaultValue":0.0,"placeholder":null,"help":"对已出现过的话题施加惩罚（0 = 关闭）","required":false},{"name":"frequencyPenalty","label":"Frequency Penalty","type":"FLOAT","min":-2.0,"max":2.0,"step":0.1,"precision":2,"defaultValue":0.0,"placeholder":null,"help":"对重复词施加惩罚（0 = 关闭）","required":false}]}', 'openai', 'https://api.openai.com', 'builtin', 1, 't', 't', '2026-07-09 13:54:17.297334', '2026-07-09 13:54:17.297334', NULL);
