INSERT INTO "public"."agent_prompt_template" VALUES ('3f9c5f3241a5fd02e87711bdd654b091', 'default', 'summarize-en', 'summarization', 'Concise English summary in one paragraph.', 'You are a concise summarizer. Read the passage and write ONE paragraph capturing the essential points.

Passage:
{{#input#}}', '["summary","en"]', '2026-07-09 13:54:17.389338', '2026-07-09 13:54:17.389338');
INSERT INTO "public"."agent_prompt_template" VALUES ('8fd7be44119dd2faa01a95078ef32de6', 'default', 'classify-intent', 'classifier', 'Route a user message into an intent id (uses {{#categories#}}).', 'You are a strict intent classifier. Pick ONE category id from the list.
Reply with ONLY the id.
Categories:
{{#categories#}}', '["classifier"]', '2026-07-09 13:54:17.393338', '2026-07-09 13:54:17.393338');
INSERT INTO "public"."agent_prompt_template" VALUES ('501e7b9da285541a9e323c7910965cd7', 'default', 'extract-json', 'extraction', 'Extract structured JSON matching a supplied schema.', 'Extract the fields defined by the JSON schema from the input. Reply with ONLY the JSON object, no code fences, no prose. Use null when a field is missing.

Schema:
{{#schema#}}

Input:
{{#input#}}', '["json","extraction"]', '2026-07-09 13:54:17.396337', '2026-07-09 13:54:17.396337');

