-- ----------------------------
-- Table structure for document_ingest_queue
-- ----------------------------
DROP TABLE IF EXISTS "public"."document_ingest_queue";
CREATE TABLE "public"."document_ingest_queue" (
  "document_id" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "dataset_id" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "tenant_id" varchar(64) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'default'::character varying,
  "filename" varchar(512) COLLATE "pg_catalog"."default",
  "source_type" varchar(32) COLLATE "pg_catalog"."default",
  "raw_text" text COLLATE "pg_catalog"."default",
  "retry_count" int4 DEFAULT 0,
  "created_at" timestamp(6),
  "updated_at" timestamp(6),
  "parsed_document_json" text COLLATE "pg_catalog"."default"
)
;

-- ----------------------------
-- Records of document_ingest_queue
-- ----------------------------

-- ----------------------------
-- Table structure for document_segments
-- ----------------------------
DROP TABLE IF EXISTS "public"."document_segments";
CREATE TABLE "public"."document_segments" (
  "id" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "tenant_id" varchar(64) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'default'::character varying,
  "dataset_id" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "document_id" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "position" int4,
  "content" text COLLATE "pg_catalog"."default",
  "token_count" int4,
  "keywords" text COLLATE "pg_catalog"."default",
  "metadata_json" text COLLATE "pg_catalog"."default",
  "parent_id" varchar(64) COLLATE "pg_catalog"."default",
  "vector_id" varchar(64) COLLATE "pg_catalog"."default",
  "enabled" bool DEFAULT true,
  "hash" varchar(32) COLLATE "pg_catalog"."default",
  "created_at" timestamp(6),
  "updated_at" timestamp(6)
)
;

