INSERT INTO "public"."document_segments" VALUES ('c6d8692b200d911030a5a1600e332ac3', 'default', '72e6c023249ea8ead2174e1d7f61e6f9', '4c2eae8a88671ef3c1dcc7e4385d5ae3', 29, '理学生的偏科问题？有针对性的补差措施吗？
