INSERT INTO "public"."document_segments" VALUES ('d099a8c434ce08e41349eff0c32982fd', 'default', '72e6c023249ea8ead2174e1d7f61e6f9', '4c2eae8a88671ef3c1dcc7e4385d5ae3', 91, '核心价值？
