INSERT INTO "public"."document_segments" VALUES ('693b8346c3b414d66945159b249babf3', 'default', '72e6c023249ea8ead2174e1d7f61e6f9', 'e7ed9d8d18d91f8ae7f0ae9b91df1758', 70, '：街舞、民族舞、合唱团、流行演唱、摄影、素描、书法；
5　 语言人文类：英语话剧、经典诵读、辩论与演讲；
6　 生活实践类：趣味烹饪。
68． 学校的德育工作有哪些特色？
以“五育并举、活动育人”为核心，打造多元德育体系，培养学生综合素养：
