-- ----------------------------
-- Table structure for workflows
-- ----------------------------
DROP TABLE IF EXISTS "public"."workflows";
CREATE TABLE "public"."workflows" (
  "id" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "tenant_id" varchar(64) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'default'::character varying,
  "name" varchar(255) COLLATE "pg_catalog"."default",
  "description" text COLLATE "pg_catalog"."default",
  "mode" varchar(32) COLLATE "pg_catalog"."default",
  "graph" text COLLATE "pg_catalog"."default",
  "version" varchar(32) COLLATE "pg_catalog"."default" DEFAULT 'draft'::character varying,
  "published" bool DEFAULT false,
  "created_at" timestamp(6),
  "updated_at" timestamp(6),
  "app_id" varchar(64) COLLATE "pg_catalog"."default",
  "features" text COLLATE "pg_catalog"."default",
  "environment_variables" text COLLATE "pg_catalog"."default",
  "conversation_variables" text COLLATE "pg_catalog"."default",
  "output" text COLLATE "pg_catalog"."default",
  "marked_name" varchar(255) COLLATE "pg_catalog"."default",
  "marked_comment" varchar(1024) COLLATE "pg_catalog"."default"
)
;

